mapper.sql:
WHERE 1=1

  AND m.bill_no IN (SELECT x.bill_no FROM sn_prd_mo x WHERE x.bill_no LIKE #{like} OR x.pi LIKE #{like}
    OR x.po LIKE #{like} OR x.material_code LIKE #{like} OR x.customer_code LIKE #{like})

AND m.customer_code = #{customer}
AND m.pi = #{pi}

mapper.select:
SELECT DISTINCT m.customer_code FROM sn_prd_mo m WHERE m.customer_code <> ''
AND m.customer_code LIKE #{like}

ORDER BY m.customer_code LIMIT 200

SELECT m.* FROM sn_prd_mo m WHERE m.pi <> ''
AND m.pi = #{pi}

  AND (m.pi LIKE #{like} OR m.bill_no LIKE #{like} OR m.material_code LIKE #{like} OR m.customer_code LIKE #{like})

ORDER BY m.pi, m.bill_no, m.seq LIMIT #{limit}
